import {describe,expect,it} from 'vitest'
import {answerExam,completePart,examCounts,finishHearingPlayback,hearingCanPlay,hearingResult,newExam,pauseExam,
 playHearing,readingResult,remaining,resumeExam,startSpeakingPerformance,suggestedRetakes} from './model'
import {readingSets} from '../lesen/content'
describe('A1 birleşik deneme',()=>{
 it('iki setin her birinde dört gerçek bölüm var',()=>{
  for(const n of [0,1] as const){const x=newExam(n,1000000);expect(x.part).toBe('lesen')
   expect(readingResult(x).total).toBe(readingSets[n].questions.length)
   expect(hearingResult(x).total).toBe(15);expect(x.sections.sprechen.startedAt).toBeUndefined()}
 })
 it('resmî yazılı süreleri ve sözlü 10+10 hazırlığı',()=>{
  let x=newExam(0,1000000)
  expect(remaining(x,1000000)).toBe(1500)
  x=completePart(x,2500000);expect(x.part).toBe('hoeren');expect(remaining(x,2500000)).toBe(600)
  x=completePart(x,3100000);expect(x.part).toBe('schreiben');expect(remaining(x,3100000)).toBe(1200)
  x=completePart(x,4300000);expect(x.part).toBe('sprechen');expect(x.speaking.phase).toBe('prep')
  expect(remaining(x,4300000)).toBe(600)
  x=startSpeakingPerformance(x,4900000);expect(x.speaking.phase).toBe('speech')
  expect(remaining(x,4900000)).toBe(600)
  x=completePart(x,5500000);expect(x.status).toBe('finished')
 })
 it('ara verince saat donar; yenileme aktif saati sıfırlamaz',()=>{
  let x=newExam(0,1000000)
  x=pauseExam(x,1100000);expect(remaining(x,1900000)).toBe(1400)
  x=resumeExam(x,2000000);expect(remaining(x,2000000)).toBe(1400)
  expect(remaining(x,2050000)).toBe(1350)
  expect(remaining(JSON.parse(JSON.stringify(x)),2100000)).toBe(1300)
 })
 it('tamamlanmadan otomatik başarı kaydı yoktur, boşlar yanlışa yazılmaz',()=>{
  let x=newExam(0,1000000)
  const q=readingSets[0].questions[0]
  x=answerExam(x,q.id,q.answer,1000001)
  const r=readingResult(x)
  expect(r.correct).toBe(1);expect(r.wrong).toBe(0)
  expect(r.blank).toBe(r.total-1)
  expect(examCounts(x).completedParts).toBe(0)
 })
 it('dinleme birinci görev 1, ikinci 2 hak kullanır',()=>{
  let x=newExam(0,1000000);x=completePart(x,2500000)
  x=playHearing(x,1);expect(hearingCanPlay(x,1)).toBe(true)
  x=finishHearingPlayback(x,1);expect(hearingCanPlay(x,1)).toBe(false)
  x=playHearing(x,2);x=finishHearingPlayback(x,2)
  expect(hearingCanPlay(x,2)).toBe(true)
  x=playHearing(x,2);x=finishHearingPlayback(x,2)
  expect(hearingCanPlay(x,2)).toBe(false)
 })
 it('gerçek kayıtlara göre tekrar önerir, sahte puan üretmez',()=>{
  const x=newExam(0,1000000)
  expect(suggestedRetakes(x)).toEqual(['lesen','hoeren','schreiben','sprechen'])
  expect(x).not.toHaveProperty('correctCount')
 })
})

import {readingSets} from '../lesen/content'
import {hearingSets,matchesAnswer} from '../hoeren/content'
import {writingTasks} from '../schreiben/content'
import {speakingSets} from '../sprechen/content'

export type ExamPart='lesen'|'hoeren'|'schreiben'|'sprechen'
export const PARTS:ExamPart[]=['lesen','hoeren','schreiben','sprechen']
export const PART_LABELS:Record<ExamPart,string>={lesen:'Lesen',hoeren:'Hören',schreiben:'Schreiben',sprechen:'Sprechen'}
export const LIMITS:Record<ExamPart,number>={lesen:1500,hoeren:600,schreiben:1200,sprechen:600}
export type Three=1|2|3
export const HEARING_LIMITS:Record<Three,number>={1:1,2:2,3:1}
export interface ExamPartData {
 startedAt?:string;endsAt?:string;finishedAt?:string;pausedAt?:string;
 questionIndex:number;answers:Record<string,string>
}
export interface ExamRun {
 id:string;kind:'integrated-exam';version:1;setIndex:0|1;status:'active'|'paused'|'finished';
 startedAt:string;updatedAt:string;finishedAt?:string;part:ExamPart;
 sections:Record<ExamPart,ExamPartData>;
 hearing:{part:Three;plays:Record<Three,number>;completed:Record<Three,number>;positions:Record<Three,number>};
 writing:{form:Record<string,string>;email:string};
 speaking:{phase:'prep'|'speech';topics:string[];sceneId:string;step:number;notes:string;
    recording?:{id:string;duration:number;size:number;mime:string;createdAt:string}}
}
const stamp=(time:number)=>new Date(time).toISOString()
export const selectedSet=(run:ExamRun)=>({
 lesen:readingSets[run.setIndex],hoeren:hearingSets[run.setIndex],
 schreiben:writingTasks[run.setIndex],sprechen:speakingSets[run.setIndex]
})
const blank=():ExamPartData=>({questionIndex:0,answers:{}})
export function newExam(setIndex:0|1,now=Date.now()):ExamRun {
 const start=stamp(now)
 return {
 id:'exam:a1:'+now+':'+setIndex,kind:'integrated-exam',version:1,setIndex,status:'active',
 startedAt:start,updatedAt:start,part:'lesen',
 sections:{lesen:{...blank(),startedAt:start,endsAt:stamp(now+LIMITS.lesen*1000)},hoeren:blank(),schreiben:blank(),sprechen:blank()},
 hearing:{part:1,plays:{1:0,2:0,3:0},completed:{1:0,2:0,3:0},positions:{1:0,2:0,3:0}},
 writing:{form:{},email:''},speaking:{phase:'prep',topics:[],sceneId:'',step:0,notes:''}
 }
}
export const remaining=(run:ExamRun,now=Date.now()):number=>{
 const section=run.sections[run.part]
 if(!section.endsAt||run.status==='finished')return 0
 const ref=run.status==='paused'&&section.pausedAt?Date.parse(section.pausedAt):now
 return Math.max(0,Math.ceil((Date.parse(section.endsAt)-ref)/1000))
}
export const timeText=(secs:number)=>String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')
export function pauseExam(run:ExamRun,now=Date.now()):ExamRun{
 if(run.status!=='active')return run
 const sections={...run.sections,[run.part]:{...run.sections[run.part],pausedAt:stamp(now)}}
 return {...run,status:'paused',sections,updatedAt:stamp(now)}
}
export function resumeExam(run:ExamRun,now=Date.now()):ExamRun{
 if(run.status!=='paused')return run
 const part=run.part, section=run.sections[part]
 const ms=Math.max(0,now-Date.parse(section.pausedAt||stamp(now)))
 const sections={...run.sections,[part]:{...section,pausedAt:undefined,endsAt:section.endsAt?stamp(Date.parse(section.endsAt)+ms):undefined}}
 return {...run,status:'active',sections,updatedAt:stamp(now)}
}
export function answerExam(run:ExamRun,id:string,value:string,now=Date.now()):ExamRun {
 const section=run.sections[run.part]
 return {...run,sections:{...run.sections,[run.part]:{...section,answers:{...section.answers,[id]:value}}},updatedAt:stamp(now)}
}
export const hearingPending=(run:ExamRun,part:Three)=>run.hearing.plays[part]>run.hearing.completed[part]
export const hearingCanPlay=(run:ExamRun,part:Three)=>hearingPending(run,part)||run.hearing.plays[part]<HEARING_LIMITS[part]
export function playHearing(run:ExamRun,part:Three,now=Date.now()):ExamRun{
 if(!hearingCanPlay(run,part)||hearingPending(run,part))return run
 return {...run,hearing:{...run.hearing,plays:{...run.hearing.plays,[part]:run.hearing.plays[part]+1}},updatedAt:stamp(now)}
}
export function rememberHearing(run:ExamRun,part:Three,position:number):ExamRun{
 return {...run,hearing:{...run.hearing,positions:{...run.hearing.positions,[part]:Math.max(0,position)}}}
}
export function finishHearingPlayback(run:ExamRun,part:Three):ExamRun{
 return {...run,hearing:{...run.hearing,completed:{...run.hearing.completed,[part]:Math.min(run.hearing.plays[part],run.hearing.completed[part]+1)},positions:{...run.hearing.positions,[part]:0}}}
}
export function startSpeakingPerformance(run:ExamRun,now=Date.now()):ExamRun{
 if(run.part!=='sprechen'||run.speaking.phase!=='prep')return run
 return {...run,speaking:{...run.speaking,phase:'speech'},
  sections:{...run.sections,sprechen:{...run.sections.sprechen,endsAt:stamp(now+LIMITS.sprechen*1000)}},updatedAt:stamp(now)}
}
export function completePart(run:ExamRun,now=Date.now()):ExamRun{
 if(run.status!=='active')return run
 if(run.part==='sprechen'&&run.speaking.phase==='prep')return startSpeakingPerformance(run,now)
 const part=run.part,idx=PARTS.indexOf(part),finishedAt=stamp(now)
 const current={...run.sections[part],finishedAt,pausedAt:undefined}
 const sections={...run.sections,[part]:current}
 if(idx===PARTS.length-1)return {...run,sections,status:'finished',finishedAt,updatedAt:finishedAt}
 const next=PARTS[idx+1]
 sections[next]={...sections[next],startedAt:finishedAt,endsAt:stamp(now+(next==='sprechen'?600:LIMITS[next])*1000)}
 return {...run,sections,part:next,updatedAt:finishedAt}
}
export function readingResult(run:ExamRun){
 const s=selectedSet(run).lesen,answers=run.sections.lesen.answers
 const correct=s.questions.filter(q=>answers[q.id]===q.answer).length
 const answered=s.questions.filter(q=>Boolean(answers[q.id])).length
 return {correct,wrong:answered-correct,answered,blank:s.questions.length-answered,total:s.questions.length,
 wrongItems:s.questions.filter(q=>Boolean(answers[q.id])&&answers[q.id]!==q.answer)
  .map(q=>({id:q.id,part:q.part,prompt:q.prompt,user:answers[q.id],answer:q.answer,why:q.explanation}))}
}
export function hearingResult(run:ExamRun){
 const s=selectedSet(run).hoeren,answers=run.sections.hoeren.answers,qs=s.units.flatMap(u=>u.questions)
 const correct=qs.filter(q=>matchesAnswer(q,answers[q.id])).length
 const answered=qs.filter(q=>Boolean(answers[q.id]?.trim())).length
 return {correct,wrong:answered-correct,answered,blank:qs.length-answered,total:qs.length,
 wrongItems:qs.filter(q=>Boolean(answers[q.id]?.trim())&&!matchesAnswer(q,answers[q.id]))
 .map(q=>({id:q.id,part:q.part,prompt:q.prompt,user:answers[q.id],answer:q.answer,why:q.explanationTr}))}
}
export function examCounts(run:ExamRun) {
 const lesen=readingResult(run),hoeren=hearingResult(run)
 const form=selectedSet(run).schreiben.fields
 const filled=form.filter(f=>Boolean(run.writing.form[f.id]?.trim())).length
 return {lesen,hoeren,formFilled:filled,formTotal:form.length,emailWords:run.writing.email.trim()?run.writing.email.trim().split(/\s+/).length:0,
 topics:run.speaking.topics.length,recordings:run.speaking.recording?1:0,
 completedParts:PARTS.filter(p=>Boolean(run.sections[p].finishedAt)).length}
}
export function suggestedRetakes(run:ExamRun):ExamPart[]{
 const l=readingResult(run),h=hearingResult(run),suggest:ExamPart[]=[]
 if(l.wrong>0||l.blank>0)suggest.push('lesen')
 if(h.wrong>0||h.blank>0)suggest.push('hoeren')
 if(examCounts(run).formFilled<10||!run.writing.email.trim())suggest.push('schreiben')
 if(!run.speaking.recording)suggest.push('sprechen')
 return suggest
}

import { useEffect, useRef, useState } from 'react'
import { deleteRecord, listRecords, putRecord } from '../../storage/db'
import { hearingSets, getHearingSet, matchesAnswer, type HearingQuestion, type HearingSet, type Part, type Mode } from './content'
import Picture from '../lesen/Pictures'
import {
 canReplay, completePlayback, countResults, draftId, finishAttempt, formatTime, hasPendingPlayback,
 makeAttempt, registerPlay, remaining, rememberPlayback, selectedValue, updateAnswer, PLAY_LIMIT,
 type HearingAttempt
} from './logic'
import './hoeren.css'

type Screen = 'sets' | 'taking' | 'result'
const isHearing=(a:HearingAttempt)=>a?.module==='hoeren'&&Boolean(getHearingSet(a.taskId))
const allQuestions=(s:HearingSet)=>s.units.flatMap(u=>u.questions)

export default function HoerenView() {
 const [screen,setScreen]=useState<Screen>('sets')
 const [active,setActive]=useState<HearingAttempt|null>(null)
 const activeRef=useRef<HearingAttempt|null>(null)
 const [drafts,setDrafts]=useState<HearingAttempt[]>([])
 const [history,setHistory]=useState<HearingAttempt[]>([])
 const [saving,setSaving]=useState(false)
 const [error,setError]=useState('')
 const [audioError,setAudioError]=useState('')
 const [playing,setPlaying]=useState(false)
 const [showTranscript,setShowTranscript]=useState(false)
 const [now,setNow]=useState(Date.now)
 const [busy,setBusy]=useState(false)
 const [loading,setLoading]=useState(true)
 const audioRef=useRef<HTMLAudioElement|null>(null)
 const queue=useRef<Promise<void>>(Promise.resolve())
 const previousTime=useRef(0)
 const preventFinish=useRef(false)
 const currentPart=useRef<Part|0>(0)

 const setAttempt=(a:HearingAttempt|null)=>{activeRef.current=a;setActive(a)}
 const listAll=async()=>{
   const rows=(await listRecords<HearingAttempt>('attempts')).filter(isHearing)
   setDrafts(rows.filter(a=>!a.finishedAt).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)))
   setHistory(rows.filter(a=>a.finishedAt).sort((a,b)=>(b.finishedAt||'').localeCompare(a.finishedAt||'')))
 }
 useEffect(()=>{
   let mounted=true
   listRecords<HearingAttempt>('attempts').then(rows=>{
     if(!mounted)return
     const ours=rows.filter(isHearing)
     setDrafts(ours.filter(a=>!a.finishedAt).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)))
     setHistory(ours.filter(a=>a.finishedAt).sort((a,b)=>(b.finishedAt||'').localeCompare(a.finishedAt||'')))
   }).catch(()=>{if(mounted)setError('Cihaz kayıtlarına erişilemiyor. Depolama ayarlarını kontrol et.')})
     .finally(()=>{if(mounted)setLoading(false)})
   return()=>{mounted=false}
 },[])
 const save=(a:HearingAttempt)=>{
   setAttempt(a)
   setSaving(true)
   queue.current=queue.current.catch(()=>{}).then(()=>putRecord('attempts',a))
     .catch(()=>setError('Kayıt başarısız. Bu ekrandan çıkmadan depolama iznini kontrol et.'))
     .finally(()=>setSaving(false))
 }
 const change=(f:(a:HearingAttempt)=>HearingAttempt)=>{
   const curr=activeRef.current
   if(curr&&!curr.finishedAt&&!preventFinish.current)save(f(curr))
 }
 const start=async(set:HearingSet,mode:Mode)=>{
   setError('');setAudioError('')
   const previous=drafts.find(a=>a.id===draftId(set.id,mode))
   if(previous){
     setAttempt(previous);setNow(Date.now());setScreen('taking');setShowTranscript(false)
     return
   }
   const a=makeAttempt(set,mode)
   try{
     await putRecord('attempts',a)
     setAttempt(a);setDrafts(xs=>[a,...xs]);setNow(Date.now());setScreen('taking')
   }catch{setError('Yeni çalışmayı kaydedemedik. Tarayıcıda depolama alanı gerekir.')}
 }
 const finish=async(reason:'submitted'|'timeout')=>{
   if(preventFinish.current||!activeRef.current)return
   preventFinish.current=true
   setBusy(true);setError('')
   try{
     audioRef.current?.pause()
     await queue.current
     const a=activeRef.current!
     const final=finishAttempt(a,a.mode==='exam'&&remaining(a)===0?'timeout':reason)
     await putRecord('attempts',final)
     await deleteRecord('attempts',a.id)
     setAttempt(final);setScreen('result');setShowTranscript(false)
     await listAll()
     window.dispatchEvent(new Event('ayda:progress-changed'))
   }catch{
     setError('Sonuç kaydedilemedi; yeniden dene. Cevapların henüz silinmedi.')
   }finally{preventFinish.current=false;setBusy(false)}
 }
 useEffect(()=>{
   if(screen!=='taking'||active?.mode!=='exam')return
   const tick=()=>{
     const timestamp=Date.now()
     setNow(timestamp)
     const a=activeRef.current
     if(a&&!a.finishedAt&&remaining(a,timestamp)===0)void finish('timeout')
   }
   tick()
   const timer=window.setInterval(tick,1000)
   return()=>window.clearInterval(timer)
 },[screen,active?.id,active?.endsAt,active?.mode])
 const set=active?getHearingSet(active.taskId):undefined
 const questions=set?allQuestions(set):[]
 const q=active?questions[active.currentIndex]:undefined
 const unit=q?set?.units.find(u=>u.part===q.part):undefined
 const answer=q&&active?selectedValue(active,q.id):''
 const result=set&&active?countResults(active,set):undefined
 const part=q?.part??1
 const plays=active?.plays[part]||0
 const canPlay=active?canReplay(active,part):false

 useEffect(()=>{
   if(!unit)return
   if(currentPart.current!==unit.part){
     audioRef.current?.pause()
     currentPart.current=unit.part
     setPlaying(false);setAudioError('');setShowTranscript(false);previousTime.current=0
   }
 },[unit?.part,active?.taskId])
 useEffect(()=>{
   if(screen!=='taking')return
   const onVisibility=()=>{
     if(document.hidden&&activeRef.current?.mode==='exam'&&!audioRef.current?.paused)
       audioRef.current?.pause()
   }
   document.addEventListener('visibilitychange',onVisibility)
   return()=>document.removeEventListener('visibilitychange',onVisibility)
 },[screen])
 const saveAudioPosition=(force=false)=>{
   const a=activeRef.current, audio=audioRef.current
   if(!a||!audio||a.mode==='practice'||!hasPendingPlayback(a,part))return
   if(!force&&Math.abs(audio.currentTime-previousTime.current)<3)return
   previousTime.current=audio.currentTime
   change(old=>rememberPlayback(old,part,audio.currentTime))
 }
 const playAudio=()=>{
   const a=activeRef.current,audio=audioRef.current
   if(!a||!audio||busy)return
   setAudioError('')
   if(a.mode==='exam'&&!canReplay(a,part))return
   if(!audio.paused)return
   const resume=a.mode==='exam'&&hasPendingPlayback(a,part)
   if(resume){
     const position=a.audioPositions?.[part]||0
     if(Number.isFinite(audio.duration)&&audio.duration>position+0.5)audio.currentTime=position
   }else audio.currentTime=0
   setBusy(true)
   // play() must be invoked synchronously within the user gesture on mobile.
   const promise=audio.play()
   Promise.resolve(promise).then(()=>{
     if(!resume&&a.mode==='exam')change(old=>registerPlay(old,part))
     setPlaying(true)
   }).catch(()=>{
     setAudioError('Ses başlatılamadı. İnternet bağlantısını, tarayıcı ses iznini ve dosya yüklenmesini kontrol et.')
   }).finally(()=>setBusy(false))
 }
 const pauseAudio=()=>{
   const audio=audioRef.current
   if(!audio)return
   audio.pause()
   saveAudioPosition(true)
   setPlaying(false)
 }
 const onEnded=()=>{
   setPlaying(false)
   if(activeRef.current?.mode==='exam')
     change(a=>completePlayback(a,part))
 }
 const back=()=>{
   audioRef.current?.pause()
   void listAll()
   setScreen('sets');setAudioError('');setShowTranscript(false)
 }
 const goto=(index:number)=>{if(q&&questions[index]?.part!==q.part){audioRef.current?.pause();setPlaying(false)}change(a=>({...a,currentIndex:index,updatedAt:new Date().toISOString()}))}
 const sendAnswer=(val:string)=>{if(q)change(a=>updateAnswer(a,q.id,val))}
 const statusLabel=active?.mode==='exam' ? (hasPendingPlayback(active,part)?'Yarım kalan oynatmaya devam edebilirsin': (PLAY_LIMIT[part]-plays)+' oynatma hakkı kaldı') : 'Çalışma modunda tekrar sınırsız'
 return <div className="hoeren-app">
 {error&&<p role="alert" className="hoeren-error">{error}</p>}
 {screen==='sets'&&<>
   <header className="hoeren-intro"><div><span className="hoeren-kicker">AŞAMA 3 · HÖREN</span><h2>Dinle. Anla. Cevapla.</h2><p>İki özgün A1 dinleme seti ve altı gerçek ses dosyası. Sesler çevrimdışı üretilmiş sentetik Almanca konuşmalardır; resmî ÖSD kayıtları değildir.</p></div><div className="hoeren-intro-number"><strong>30</strong><small>SORU</small></div></header>
   {!loading&&hearingSets.map((set,index)=><article className="hoeren-set" key={set.id}>
     <div className="hoeren-set-head"><span className="hoeren-set-index">0{index+1}</span><div><h3>{set.title}</h3><p>{set.subtitle}</p></div><span className="hoeren-count">15 SORU</span></div>
     <div className="hoeren-part-list"><span>5 görsel eşleştirme</span><span>5 kısa not</span><span>5 röportaj</span></div>
     <div className="hoeren-set-actions">{(['practice','exam'] as const).map(mode=>{
       const previous=drafts.find(a=>a.id===draftId(set.id,mode))
       return <button key={mode} type="button" className={mode==='practice'?'hoeren-primary':'hoeren-outline'} onClick={()=>void start(set,mode)}>{previous?'Devam et · ':''}{mode==='practice'?'Çalışma modu':'~10 dk sınav modu'}{previous&&<small>{previous.answers.filter(x=>String(x.value).trim()).length}/15 cevap</small>}</button>
     })}</div>
   </article>)}
   {loading&&<p>Kaydedilmiş çalışmalar yükleniyor…</p>}
   {history.length>0&&<section className="hoeren-history"><h3>Önceki sonuçların</h3>{history.slice(0,8).map(x=><button key={x.id} onClick={()=>{setAttempt(x);setScreen('result')}}><span><strong>{getHearingSet(x.taskId)?.title}</strong><small>{x.mode==='exam'?'Sınav':'Çalışma'} · {new Date(x.finishedAt!).toLocaleDateString('tr-TR')}</small></span><b>{x.correctCount}/{x.questionCount}</b></button>)}</section>}
   <div className="hoeren-guidance"><strong>Gerçek dinleme nasıl çalışır?</strong><p>Sınavda Aufgabe 1 ve 3 birer kez, Aufgabe 2 en fazla iki kez dinlenir. Başlamadan önce soruları incele. Mobil tarayıcıda sesi açmak için dokunmalısın. Resmî ÖSD puanı yerine gerçek doğru sayısı gösterilir.</p></div>
 </>}
 {screen==='taking'&&set&&q&&unit&&active&&result&&<>
   <div className="hoeren-session-head"><button className="hoeren-link" onClick={back}>‹ Setlere dön</button><div className="hoeren-session-status"><small>{error?'Kayıt sorunu':saving?'Kaydediliyor':'Cihazda kayıt'}</small>{active.mode==='exam'?<strong className={'hoeren-clock '+(remaining(active,now)<60?'danger':'')}>{formatTime(remaining(active,now))}</strong>:<b>ÇALIŞMA</b>}</div></div>
   <div className="hoeren-status-bar"><strong>{set.title}</strong><span>{result.answered}/15 yanıt</span></div><div className="hoeren-bar"><span style={{width:(result.answered/15*100)+'%'}}/></div>
   <nav className="hoeren-tabs" aria-label="Dinleme görevleri">{set.units.map(u=><button key={u.part} className={part===u.part?'selected':''} onClick={()=>goto(questions.findIndex(ques=>ques.part===u.part))}>Aufgabe {u.part}<small>{u.part===1?'Resimler':u.part===2?'Bilgiler':'Röportajlar'}</small></button>)}</nav>
   <section className="hoeren-audio-panel">
     <div><span className="hoeren-kicker">ORİJİNAL AYDA DEMO SESİ</span><h2>{unit.label} · {unit.part===1?'Görseller':unit.part===2?'Not tutma':'Röportajlar'}</h2><p>{unit.descriptionTr}</p><small lang="de">{unit.instructionDe}</small></div>
     <div className="hoeren-player">
       <audio key={unit.audio} ref={audioRef} preload="metadata" src={unit.audio} controls={active.mode==='practice'}
         onPlay={()=>setPlaying(true)}
         onPause={()=>{setPlaying(false);saveAudioPosition(true)}}
         onTimeUpdate={()=>saveAudioPosition()}
         onEnded={onEnded}
